interface OpenNextWorker {
  fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> | Response;
}

// Loaded on first use instead of at the top of the file. The OpenNext bundle (Next, React, the DB layer) is
// large, and evaluating it is most of a cold start. Cache hits, redirects and the cheap 404s never need it,
// so they are answered without paying that cost. The promise is memoised: one load per isolate.
let openNextPromise: Promise<OpenNextWorker> | null = null;
function loadOpenNext(): Promise<OpenNextWorker> {
  if (!openNextPromise) {
    // @ts-ignore - generated by `opennextjs-cloudflare build`, it does not exist while `next build` type-checks.
    openNextPromise = import('./.open-next/worker.js').then((m: { default: OpenNextWorker }) => m.default);
    // A failed load must not be remembered, or the isolate would answer 500 until it is recycled.
    openNextPromise.catch(() => {
      openNextPromise = null;
    });
  }
  return openNextPromise;
}

interface WorkerEnv {
  CF_VERSION_METADATA?: { id?: string };
  [key: string]: unknown;
}

interface WorkerCtx {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException?(): void;
}

const SESSION_COOKIE = 'next-auth';
const MAX_URL_LENGTH = 300;
const NOT_FOUND_TTL = 60;
// An entry stays physically in the cache this many times longer than its freshness window. Once past the
// window it is still served instantly (stale-while-revalidate) while one background render refreshes it,
// so visitors never wait for a D1 round trip and a burst of traffic triggers a single render per data centre.
const STALE_FACTOR = 5;
const CACHED_AT_HEADER = 'X-Cached-At';
const refreshing = new Set<string>();
const RSC_VARY_HEADERS = ['next-router-state-tree', 'next-router-prefetch', 'next-router-segment-prefetch', 'next-url'];
const RESPONSE_VARY = 'rsc, next-router-state-tree, next-router-prefetch, next-router-segment-prefetch, accept-encoding';

const KNOWN_EXACT = new Set([
  '/', '/news', '/programs', '/videos', '/search', '/privacy', '/terms', '/admin',
  '/sitemap.xml', '/news-sitemap.xml', '/robots.txt', '/favicon.ico', '/favicon.svg', '/logo.svg', '/lens-icon.svg',
  '/live-placeholder.html', '/header-skyline.avif', '/og-default.png', '/logo-512.png', '/apple-touch-icon.png',
  '/scope-media-logo-v2.svg', '/scope-media-logo-v2-dark.svg', '/scope-media-logo-white.svg',
]);
const KNOWN_PREFIXES = ['/news/', '/category/', '/programs/', '/admin/', '/api/', '/_next/', '/.well-known/'];

/** True for paths that exist in this app; everything else is answered with a cheap 404 (no Next render). */
function isKnownPath(pathname: string): boolean {
  return KNOWN_EXACT.has(pathname) || KNOWN_PREFIXES.some((p) => pathname.startsWith(p));
}

/** Returns the cache lifetime (seconds) for a public path, or 0 when the path must not be cached. */
function ttlForPath(pathname: string): number {
  if (pathname === '/') return 120;
  if (pathname.startsWith('/news/')) return 120;
  if (pathname.startsWith('/programs/')) return 120;
  if (pathname === '/programs' || pathname === '/videos' || pathname === '/search') return 300;
  if (pathname.startsWith('/category/')) return 120;
  if (pathname === '/privacy' || pathname === '/terms') return 600;
  if (pathname === '/sitemap.xml') return 600;
  if (pathname === '/news-sitemap.xml') return 300;
  if (pathname === '/robots.txt') return 3600;
  return 0;
}

function getEdgeCache(): Cache | null {
  const store = (globalThis as unknown as { caches?: { default?: Cache } }).caches;
  return store?.default ?? null;
}

async function sha1Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(input));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
}

const TRACKING_PARAMS = ['fbclid', 'gclid', 'igshid', 'mc_cid', 'mc_eid', 'ref', 'ref_src', 'twclid'];

/** Removes tracking-only query params so every share/click of the same page maps to ONE cache entry. */
function stripTracking(u: URL) {
  for (const p of [...u.searchParams.keys()]) {
    if (p.startsWith('utm_') || TRACKING_PARAMS.includes(p)) u.searchParams.delete(p);
  }
}

async function buildCacheKey(request: Request, url: URL, env: WorkerEnv): Promise<Request> {
  const key = new URL(url.toString());
  stripTracking(key);
  key.searchParams.set('__v', env.CF_VERSION_METADATA?.id || 'dev');

  if (request.headers.get('rsc') === '1') {
    const variant = RSC_VARY_HEADERS.map((h) => request.headers.get(h) || '').join('|');
    key.searchParams.set('__rsc', await sha1Hex(variant));
  }
  return new Request(key.toString(), { method: 'GET' });
}

async function handle(request: Request, env: WorkerEnv, ctx: WorkerCtx): Promise<Response> {
  const passThrough = async (): Promise<Response> => (await loadOpenNext()).fetch(request, env, ctx);

  if (!isKnownPath(new URL(request.url).pathname)) {
    return new Response('Not found', {
      status: 404,
      headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'public, max-age=300' },
    });
  }

  if (request.method !== 'GET') return passThrough();

  const url = new URL(request.url);
  const ttl = ttlForPath(url.pathname);
  const cache = getEdgeCache();
  if (!ttl || !cache || request.url.length > MAX_URL_LENGTH) return passThrough();
  if ((request.headers.get('cookie') || '').includes(SESSION_COOKIE)) return passThrough();

  let key: Request;
  try {
    key = await buildCacheKey(request, url, env);
    const hit = await cache.match(key);
    if (hit) {
      const cachedAt = Number(hit.headers.get(CACHED_AT_HEADER)) || 0;
      const fresh = !cachedAt || Date.now() - cachedAt < (hit.status === 200 ? ttl : NOT_FOUND_TTL) * 1000;
      if (!fresh && !refreshing.has(key.url)) {
        refreshing.add(key.url);
        ctx.waitUntil(
          renderAndStore(passThrough, cache, key, ttl)
            .catch(() => {})
            .finally(() => refreshing.delete(key.url)),
        );
      }
      const response = new Response(hit.body, hit);
      response.headers.set('X-Worker-Cache', fresh ? 'HIT' : 'STALE');
      response.headers.delete(CACHED_AT_HEADER);
      return response;
    }
  } catch {
    // Cache trouble must never break the site: fall through to a normal render.
    return passThrough();
  }

  const response = await passThrough();
  if (!isCacheable(response)) return response;

  ctx.waitUntil(storeResponse(cache, key, response.clone(), ttl).catch(() => {}));

  const out = new Response(response.body, response);
  out.headers.set('X-Worker-Cache', 'MISS');
  return out;
}

function isCacheable(response: Response): boolean {
  return (
    (response.status === 200 || response.status === 404) &&
    !response.headers.has('set-cookie') &&
    !/text\/event-stream/i.test(response.headers.get('content-type') || '')
  );
}

async function storeResponse(cache: Cache, key: Request, response: Response, ttl: number): Promise<void> {
  const freshFor = response.status === 200 ? ttl : NOT_FOUND_TTL;
  const toStore = new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: new Headers(response.headers),
  });
  toStore.headers.set('Cache-Control', `public, max-age=${freshFor * STALE_FACTOR}`);
  toStore.headers.set(CACHED_AT_HEADER, String(Date.now()));
  toStore.headers.delete('vary');
  toStore.headers.delete('set-cookie');
  await cache.put(key, toStore);
}

async function renderAndStore(
  render: () => Promise<Response>,
  cache: Cache,
  key: Request,
  ttl: number,
): Promise<void> {
  const response = await render();
  if (isCacheable(response)) await storeResponse(cache, key, response, ttl);
}

export default {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerCtx): Promise<Response> {
    const response = await handle(request, env, ctx);

    // Entries come back from the cache with the stored (internal) Cache-Control. Browsers get a short
    // lifetime: repeat views and back-navigation inside it never reach the Worker (= no invocation),
    // while anything older is revalidated so nobody pins stale HTML across a deploy.
    if (response.headers.get('X-Worker-Cache')) {
      const headers = new Headers(response.headers);
      const browserTtl = response.status === 200 ? Math.min(60, ttlForPath(new URL(request.url).pathname)) : 0;
      headers.set('Cache-Control', browserTtl > 0 ? `public, max-age=${browserTtl}` : 'public, max-age=0, must-revalidate');
      headers.set('Vary', RESPONSE_VARY);
      return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
    }
    return response;
  },
};
